import unittest


class TestUniqueDigits(unittest.TestCase):

    def test_mixed_odd_and_even_digits(self):
        self.assertEqual(unique_digits([15, 33, 1422, 1]), [1, 15, 33])

    def test_all_odd_digits(self):
        self.assertEqual(unique_digits([135, 379, 11]), [11, 135, 379])

    def test_no_odd_digit_elements(self):
        self.assertEqual(unique_digits([152, 323, 1422, 10]), [])

    def test_empty_list(self):
        self.assertEqual(unique_digits([]), [])

    def test_single_element_odd(self):
        self.assertEqual(unique_digits([7]), [7])

    def test_single_element_even(self):
        self.assertEqual(unique_digits([8]), [])

    def test_result_is_sorted(self):
        self.assertEqual(unique_digits([31, 13, 5, 571, 111]), [5, 13, 31, 111, 571])

    def test_duplicates_preserved(self):
        self.assertEqual(unique_digits([13, 13, 5]), [5, 13, 13])

    def test_zero_excluded(self):
        self.assertEqual(unique_digits([0, 1]), [1])

    def test_multi_digit_with_zero(self):
        self.assertEqual(unique_digits([101, 111]), [111])

    def test_large_numbers(self):
        self.assertEqual(unique_digits([13579, 24680, 97531]), [13579, 97531])

    def test_return_type_is_list(self):
        self.assertIsInstance(unique_digits([1, 2, 3]), list)

    def test_input_not_modified(self):
        original = [15, 33, 1422, 1]
        copy = list(original)
        unique_digits(original)
        self.assertEqual(original, copy)


